        # Generate pattern for columns 3-27
        for c in range(3, 28):
            if grid[r][c] != 0:
                # Keep existing non-zero value (already matches pattern)
                result.append(grid[r][c])
            else:
                # Fill in using the cycle pattern
                # Need to determine the phase for this row

                # Find the first non-zero value at or after column 3
                first_pos = -1
                for oc in range(3, 28):
                    if grid[r][oc] != 0:
                        first_val = grid[r][oc]
                        first_pos = cycle.index(first_val)
                        break

                if first_pos == -1:
