# Update to fill all zeros including header columns for data rows
def construct_complete():
    """Fill all zeros completely"""
    full_grid = []

    for r in range(len(grid)):
        result = list(grid[r])

        if r < 3:
            # Header rows
            if r == 0:
                result = [1] * 28
            elif r == 1:
                result = [1] * 28
            else:  # row 2
                result = [1, 1] + [4] * 26

        else:
            # Data rows (r >= 3)
            cycle = [1, 3, 5, 7, 9]

            for c in range(28):
                if result[c] == 0:
                    if c < 3:
                        # Fill header columns with standard values
